/bin/zsh -lc "python3 -B - <<'PY'
from backend import Backend, Duplicate
from service import save

backend = Backend()
assert save(backend, 'key', 'original') == {'created': None}
print('Direct Backend: creation returns created=None')
try:
    save(backend, 'key', 'replacement')
except Duplicate:
    print('Direct Backend: duplicate raises Duplicate')
else:
    raise AssertionError('Expected Duplicate')
assert backend.rows['key'] == 'original'
print('Direct Backend: original value preserved')

class Offline:
    def put(self, key, value):
        raise OSError('offline')

try:
    save(Offline(), 'key', 'value')
except OSError as error:
    assert str(error) == 'offline'
    print('Direct Backend: operational error propagates')
else:
    raise AssertionError('Expected OSError')
PY"

